// Month-to-date through yesterday. On the 1st, "yesterday" is last month's final day, so the report shows that full previous month.
const end = $today.minus({days:1});
const start = end.startOf('month');
const range = start.day === end.day ? (start.day + ' ' + end.toFormat('MMM')) : (start.day + '-' + end.day + ' ' + end.toFormat('MMM'));
return [{json:{periodStart:start.toISODate(), periodEnd:end.toISODate(), periodLabel:range, periodType:'daily'}}];

const start = $today.startOf('week').minus({weeks:1});
const end = start.plus({days:6});
const label = start.toFormat('MMM d') + ' - ' + end.toFormat('MMM d, yyyy') + ' (Weekly)';
return [{json:{periodStart:start.toISODate(), periodEnd:end.toISODate(), periodLabel:label, periodType:'weekly'}}];

const start = $today.minus({months:1}).startOf('month');
const end = start.endOf('month');
const label = start.toFormat('MMM d') + ' - ' + end.toFormat('MMM d, yyyy') + ' (Monthly)';
return [{json:{periodStart:start.toISODate(), periodEnd:end.toISODate(), periodLabel:label, periodType:'monthly'}}];

const clean = v => String(v == null ? '' : v).trim();
const ready = [];
for (const it of items) {
  const j = it.json || {};
  if (clean(j.Status).toLowerCase() !== 'active') continue;
  const brand = {
    ...j,
    Brand_Name: clean(j.Brand_Name),
    Raw_Sheet_ID: clean(j.Raw_Sheet_ID),
    Current_Month_Report_Sheet_ID: clean(j.Current_Month_Report_Sheet_ID),
  };
  if (!brand.Brand_Name || !brand.Raw_Sheet_ID || !brand.Current_Month_Report_Sheet_ID) continue;
  ready.push({ json: brand });
}
if (!ready.length) {
  throw new Error('Brand Registry has no Active brand with Brand_Name, Raw_Sheet_ID and Current_Month_Report_Sheet_ID.');
}
// Two brands pointing at the same report workbook would overwrite each other.
const seen = {};
for (const it of ready) {
  const id = it.json.Current_Month_Report_Sheet_ID;
  if (seen[id]) {
    throw new Error('Brand Registry: "' + seen[id] + '" and "' + it.json.Brand_Name + '" share the same Current_Month_Report_Sheet_ID. Fix the registry before running.');
  }
  seen[id] = it.json.Brand_Name;
}
return ready;

// ===================== CONFIG =====================
const REQUIRED_COLUMNS = ['Date', 'Spend', 'Impressions', 'Purchases', 'Purchases_Value'];
const NUMERIC_COLUMNS  = ['Spend', 'Impressions', 'Purchases', 'Purchases_Value'];
const TABS = [
  { key: 'meta',    name: 'Daily_Raw_Meta',       needsAd: false },
  { key: 'metaAds', name: 'Daily_Raw_Meta_Ads',   needsAd: true  },
  { key: 'tt',      name: 'Daily_Raw_TikTok',     needsAd: false },
  { key: 'ttAds',   name: 'Daily_Raw_TikTok_Ads', needsAd: true  },
]; // order MUST match the "ranges" order in the "Read Raw Sheets" node
// ==================================================

const period = $('Set Period').first().json;
const brand = $('Loop brands').first().json;
const payload = $('Read Raw Sheets').first().json || {};
const brandName = String(brand.Brand_Name || '').trim();
const reportSheetId = String(brand.Current_Month_Report_Sheet_ID || '').trim();
const base = { brandName, periodLabel: period.periodLabel, periodType: period.periodType, periodStart: period.periodStart, periodEnd: period.periodEnd };
const stop = (status, reason) => [{ json: { ...base, status, reason } }];

if (!brandName || !reportSheetId) return stop('failed', 'Brand_Name or Current_Month_Report_Sheet_ID is empty in the Brand Registry.');
if (payload.error || !Array.isArray(payload.valueRanges) || payload.valueRanges.length !== TABS.length) {
  return stop('failed', 'Could not read the raw sheets: ' + JSON.stringify(payload.error || payload).slice(0, 400));
}

// ---------- helpers ----------
function num(v) { if (v == null || v === '') return 0; const n = Number(v); return Number.isFinite(n) ? n : 0; }
function round(n, p) { const f = 10 ** p; return Math.round(n * f) / f; }
function toISODate(v) {
  if (v == null || v === '') return '';
  if (typeof v === 'number' || (/^\d+(\.\d+)?$/.test(String(v).trim()) && Number(v) > 30000)) {
    const ms = (Math.floor(Number(v)) - 25569) * 86400 * 1000; // Sheets serial -> UTC date
    return new Date(ms).toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  for (const f of ['M/d/yyyy', 'M/d/yy', 'MM/dd/yyyy', 'd/M/yyyy', 'd/M/yy', 'dd/MM/yyyy']) {
    const dt = DateTime.fromFormat(s, f);
    if (dt.isValid) return dt.toISODate();
  }
  const dt = DateTime.fromISO(s);
  return dt.isValid ? dt.toISODate() : '';
}

// ---------- parse + filter each raw tab (NO fallback to "all rows") ----------
const sets = {};
const counts = {};
const warnings = [];
const problems = [];
TABS.forEach((tab, i) => {
  const values = Array.isArray(payload.valueRanges[i] && payload.valueRanges[i].values) ? payload.valueRanges[i].values : [];
  sets[tab.key] = [];
  counts[tab.key] = { totalRows: 0, inPeriod: 0, unparsedDates: 0 };
  if (!values.length) return; // tab is completely empty: legitimate (e.g. no TikTok yet)
  const headers = (values[0] || []).map(h => String(h == null ? '' : h).trim());
  const missing = REQUIRED_COLUMNS.filter(c => !headers.includes(c));
  if (tab.needsAd && !headers.includes('Ad_ID') && !headers.includes('Ad_Name')) missing.push('Ad_ID or Ad_Name');
  if (missing.length) { problems.push(tab.name + ': missing column(s) ' + missing.join(', ')); return; }
  const c = counts[tab.key];
  const parsed = [];
  for (const raw of values.slice(1)) {
    if (!Array.isArray(raw) || !raw.some(v => v !== '' && v != null)) continue;
    c.totalRows++;
    const obj = {};
    headers.forEach((h, idx) => { if (h) obj[h] = raw[idx] ?? ''; });
    const d = toISODate(obj.Date);
    if (!d) { c.unparsedDates++; continue; }
    obj._d = d;
    parsed.push(obj);
  }
  if (c.totalRows > 0 && parsed.length === 0) { problems.push(tab.name + ': none of the ' + c.totalRows + ' rows has a readable Date'); return; }
  if (c.unparsedDates > 0) warnings.push(tab.name + ': ' + c.unparsedDates + ' row(s) skipped (unreadable Date)');
  const inP = parsed.filter(r => r._d >= period.periodStart && r._d <= period.periodEnd);
  c.inPeriod = inP.length;
  for (const r of inP) for (const col of NUMERIC_COLUMNS) {
    const v = r[col];
    if (v !== '' && v != null && !Number.isFinite(Number(v))) problems.push(tab.name + ' ' + r._d + ' ' + col + ' = "' + v + '" is not a number');
  }
  sets[tab.key] = inP;
});
if (problems.length) return stop('failed', problems.slice(0, 5).join(' | '));
if (TABS.every(t => sets[t.key].length === 0)) {
  return stop('no_data', 'No raw rows for ' + period.periodStart + ' to ' + period.periodEnd + ' in any Daily_Raw_* tab. Existing report left untouched.');
}

// ---------- formatting ----------
function fmtNum(v, d = 2) { return Number(v).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d }); }
function fmtInt(v) { return Math.round(Number(v) || 0).toLocaleString('en-US'); }
function fmtMetric(metric, value) {
  if (value === '' || value == null) return '';
  if (['Impressions', 'Reach', 'Adds to cart', 'Initiate Checkout', 'Purchases', 'Profile Visits', 'Follows'].includes(metric)) return fmtInt(value);
  if (metric.includes('CTR') || metric.includes('CVR')) return fmtNum(value, 2) + '%';
  if (metric === 'Frequency' || metric === 'ROAS') return fmtNum(value, 2);
  if (metric === 'Spend' || metric === 'CPM' || metric.includes('Cost') || metric === 'Purchases Value' || metric === 'AOV') return fmtNum(value, 2);
  return String(value);
}
const pad = (values, n, width) => { while (values.length < n) values.push(new Array(width).fill('')); return values; };
const toTable = (list, cols) => list.map((r, idx) => cols.map(c => (c === '' ? '' : (c === 'Rank' || c === '##') ? idx + 1 : (r[c] ?? ''))));

// ---------- META ----------
function metaOverview(rows) {
  let spend = 0, impressions = 0, reach = 0, atc = 0, ic = 0, purchases = 0, pv = 0, clicks = 0;
  for (const r of rows) { spend += num(r.Spend); impressions += num(r.Impressions); reach += num(r.Reach); atc += num(r.Adds_to_Cart); ic += num(r.Initiate_Checkout); purchases += num(r.Purchases); pv += num(r.Purchases_Value); clicks += num(r.Clicks); }
  const frequency = reach ? impressions / reach : 0;
  const ctr = impressions ? (clicks / impressions) * 100 : 0; // outbound clicks / impressions
  const out = [
    { Metric: 'Spend', Value: round(spend, 2) }, { Metric: 'Outbound CTR', Value: round(ctr, 4) },
    { Metric: 'Impressions', Value: impressions }, { Metric: 'Reach', Value: reach },
    { Metric: 'Frequency', Value: round(frequency, 2) }, { Metric: 'Adds to cart', Value: atc },
    { Metric: 'Initiate Checkout', Value: ic }, { Metric: 'Purchases', Value: purchases },
    { Metric: 'Cost Per Purchase', Value: round(purchases ? spend / purchases : 0, 2) },
    { Metric: 'Purchases Value', Value: round(pv, 2) }, { Metric: 'ROAS', Value: round(spend ? pv / spend : 0, 4) },
    { Metric: 'AOV', Value: round(purchases ? pv / purchases : 0, 2) },
  ];
  return pad(out.map(r => [r.Metric, fmtMetric(r.Metric, r.Value)]), 20, 2);
}
function metaAdPerformance(rows) {
  const groups = {};
  for (const r of rows) {
    const key = r.Ad_ID || r.Ad_Name || '(unknown)';
    if (!groups[key]) groups[key] = { Ad_Name: r.Ad_Name, Creative_Key: r.Creative_Key, spend: 0, impressions: 0, clicks: 0, lpv: 0, atc: 0, ic: 0, purchases: 0, pv: 0, reachMax: 0 };
    const g = groups[key];
    g.spend += num(r.Spend); g.impressions += num(r.Impressions); g.clicks += num(r.Clicks); g.lpv += num(r.LPV); g.atc += num(r.Adds_to_Cart); g.ic += num(r.Initiate_Checkout); g.purchases += num(r.Purchases); g.pv += num(r.Purchases_Value); g.reachMax = Math.max(g.reachMax, num(r.Reach));
  }
  const list = Object.values(groups).map(g => ({
    'Ad Name': g.Ad_Name, 'Creative Key': g.Creative_Key, Spend: round(g.spend, 2),
    CPM: round(g.impressions ? (g.spend / g.impressions) * 1000 : 0, 2), 'Outbound CTR': round(g.impressions ? (g.clicks / g.impressions) * 100 : 0, 4),
    LPV: g.lpv, ATC: g.atc, 'Cost/ATC': round(g.atc ? g.spend / g.atc : 0, 2), 'ATC/LPV': round(g.lpv ? (g.atc / g.lpv) * 100 : 0, 4),
    IC: g.ic, 'Cost/IC': round(g.ic ? g.spend / g.ic : 0, 2), Frequency: round(g.reachMax ? g.impressions / g.reachMax : 0, 2),
    Purchases: g.purchases, 'Purchases Value': round(g.pv, 2), ROAS: round(g.spend ? g.pv / g.spend : 0, 4), AOV: round(g.purchases ? g.pv / g.purchases : 0, 2),
    'Purchase CVR%': round(g.clicks ? (g.purchases / g.clicks) * 100 : 0, 4), 'Impressions (est.)': g.impressions, 'Clicks (est.)': g.clicks,
  }));
  list.sort((a, b) => b.Spend - a.Spend);
  const cols = ['Rank', 'Ad Name', 'Spend', 'CPM', 'Outbound CTR', 'LPV', 'ATC', 'Cost/ATC', 'ATC/LPV', 'IC', 'Cost/IC', 'Frequency', 'Purchases', 'Purchases Value', 'ROAS', 'AOV', 'Purchase CVR%', 'Impressions (est.)', 'Clicks (est.)', 'Creative Key'];
  return pad(toTable(list, cols), 500, cols.length);
}
function creatives(rows, withClicksColumnU) {
  const groups = {};
  for (const r of rows) {
    const key = r.Creative_Key || '(unknown)';
    if (!groups[key]) groups[key] = { adIds: new Set(), spend: 0, impressions: 0, clicks: 0, atc: 0, ic: 0, purchases: 0, pv: 0 };
    const g = groups[key]; if (r.Ad_ID) g.adIds.add(r.Ad_ID);
    g.spend += num(r.Spend); g.impressions += num(r.Impressions); g.clicks += num(r.Clicks); g.atc += num(r.Adds_to_Cart); g.ic += num(r.Initiate_Checkout); g.purchases += num(r.Purchases); g.pv += num(r.Purchases_Value);
  }
  const list = Object.entries(groups).map(([key, g]) => ({
    'Creative Name': key, Instances: g.adIds.size || 1, Spend: round(g.spend, 2), CPM: round(g.impressions ? (g.spend / g.impressions) * 1000 : 0, 2),
    'Outbound CTR': round(g.impressions ? (g.clicks / g.impressions) * 100 : 0, 4), ATC: g.atc, IC: g.ic, Purchases: g.purchases,
    'Purchases Value': round(g.pv, 2), ROAS: round(g.spend ? g.pv / g.spend : 0, 4), AOV: round(g.purchases ? g.pv / g.purchases : 0, 2),
    Impressions: g.impressions, 'Clicks (est.)': g.clicks,
  }));
  list.sort((a, b) => b.Spend - a.Spend);
  // TikTok master sheet: Clicks (est.) sits in column U, spacer columns N:T
  const cols = withClicksColumnU
    ? ['##', 'Creative Name', 'Instances', 'Spend', 'CPM', 'Outbound CTR', 'ATC', 'IC', 'Purchases', 'Purchases Value', 'ROAS', 'AOV', 'Impressions', '', '', '', '', '', '', '', 'Clicks (est.)']
    : ['##', 'Creative Name', 'Instances', 'Spend', 'CPM', 'Outbound CTR', 'ATC', 'IC', 'Purchases', 'Purchases Value', 'ROAS', 'AOV', 'Impressions'];
  return pad(toTable(list, cols), 500, cols.length);
}
function weekly(rows) {
  const weeks = {};
  for (const r of rows) {
    const ws = DateTime.fromISO(r._d).startOf('week');
    const key = ws.toISODate();
    if (!weeks[key]) weeks[key] = { start: ws, end: ws.plus({ days: 6 }), spend: 0, purchases: 0, pv: 0 };
    const w = weeks[key];
    w.spend += num(r.Spend); w.purchases += num(r.Purchases); w.pv += num(r.Purchases_Value);
  }
  const list = Object.values(weeks).map(w => ({
    Week: w.start.toFormat('MMM d') + '-' + w.end.toFormat(w.start.month === w.end.month ? 'd' : 'MMM d'),
    Spend: round(w.spend, 2), Purchases: w.purchases, 'Cost Per Purchase': round(w.purchases ? w.spend / w.purchases : 0, 2),
    'Purchases Value': round(w.pv, 2), ROAS: w.spend ? round(w.pv / w.spend, 4) : '', AOV: round(w.purchases ? w.pv / w.purchases : 0, 2),
  }));
  list.sort((a, b) => (b.ROAS === '' ? -1 : b.ROAS) - (a.ROAS === '' ? -1 : a.ROAS));
  const cols = ['##', 'Week', 'Spend', 'Purchases', 'Cost Per Purchase', 'Purchases Value', 'ROAS', 'AOV'];
  return pad(toTable(list, cols), 60, cols.length);
}

// ---------- TIKTOK ----------
function tiktokOverview(rows) {
  let spend = 0, impressions = 0, reach = 0, atc = 0, ic = 0, purchases = 0, pv = 0, clicks = 0, profileVisits = 0, follows = 0, freqSum = 0, freqN = 0;
  for (const r of rows) {
    spend += num(r.Spend); impressions += num(r.Impressions); reach += num(r.Reach); atc += num(r.Adds_to_Cart); ic += num(r.Initiate_Checkout);
    purchases += num(r.Purchases); pv += num(r.Purchases_Value); clicks += num(r.Clicks); profileVisits += num(r.Profile_Visits); follows += num(r.Follows);
    if (r.Frequency) { freqSum += num(r.Frequency); freqN++; }
  }
  const freq = freqN ? freqSum / freqN : (reach ? impressions / reach : 0);
  const out = [
    { Metric: 'Spend', Value: round(spend, 2) }, { Metric: 'CPM', Value: round(impressions ? (spend / impressions) * 1000 : 0, 2) },
    { Metric: 'CTR', Value: round(impressions ? (clicks / impressions) * 100 : 0, 4) }, { Metric: 'Profile Visits', Value: profileVisits },
    { Metric: 'Follows', Value: follows }, { Metric: 'Impressions', Value: impressions }, { Metric: 'Reach', Value: reach },
    { Metric: 'Frequency', Value: round(freq, 2) }, { Metric: 'Adds to cart', Value: atc }, { Metric: 'Initiate Checkout', Value: ic },
    { Metric: 'Purchases', Value: purchases }, { Metric: 'Cost Per Purchase', Value: round(purchases ? spend / purchases : 0, 2) },
    { Metric: 'Purchases Value', Value: round(pv, 2) }, { Metric: 'ROAS', Value: round(spend ? pv / spend : 0, 4) },
    { Metric: 'AOV', Value: round(purchases ? pv / purchases : 0, 2) }, { Metric: 'Purchase CVR%', Value: round(clicks ? (purchases / clicks) * 100 : 0, 4) },
  ];
  return pad(out.map(r => [r.Metric, fmtMetric(r.Metric, r.Value)]), 25, 2);
}
function tiktokAdPerformance(rows) {
  const groups = {};
  for (const r of rows) {
    const key = r.Ad_ID || r.Ad_Name || '(unknown)';
    if (!groups[key]) groups[key] = { Ad_Name: r.Ad_Name, AdGroup_Name: r.AdGroup_Name, Creative_Key: r.Creative_Key, spend: 0, impressions: 0, clicks: 0, atc: 0, ic: 0, purchases: 0, pv: 0, profileVisits: 0, follows: 0, reachMax: 0 };
    const g = groups[key];
    g.spend += num(r.Spend); g.impressions += num(r.Impressions); g.clicks += num(r.Clicks); g.atc += num(r.Adds_to_Cart); g.ic += num(r.Initiate_Checkout);
    g.purchases += num(r.Purchases); g.pv += num(r.Purchases_Value); g.profileVisits += num(r.Profile_Visits); g.follows += num(r.Follows); g.reachMax = Math.max(g.reachMax, num(r.Reach));
  }
  const list = Object.values(groups).map(g => ({
    'Ad Name': g.Ad_Name, Spend: round(g.spend, 2), CPM: round(g.impressions ? (g.spend / g.impressions) * 1000 : 0, 2),
    CTR: round(g.impressions ? (g.clicks / g.impressions) * 100 : 0, 4), LPV: '', ATC: g.atc, 'Cost/ATC': round(g.atc ? g.spend / g.atc : 0, 2), 'ATC/LPV': '',
    'Checkout (IC)': g.ic, 'Cost/Checkout': round(g.ic ? g.spend / g.ic : 0, 2), Frequency: round(g.reachMax ? g.impressions / g.reachMax : 0, 2),
    Purchases: g.purchases, 'Purchases Value': round(g.pv, 2), ROAS: round(g.spend ? g.pv / g.spend : 0, 4), AOV: round(g.purchases ? g.pv / g.purchases : 0, 2),
    'Purchase CVR%': round(g.clicks ? (g.purchases / g.clicks) * 100 : 0, 4), Reach: g.reachMax, 'Profile Visits': g.profileVisits, Follows: g.follows,
    'Impressions (est.)': g.impressions, 'Clicks (est.)': g.clicks, 'Ad Group': g.AdGroup_Name, 'Creative Key': g.Creative_Key,
  }));
  list.sort((a, b) => b.Spend - a.Spend);
  const cols = ['Rank', 'Ad Name', 'Spend', 'CPM', 'CTR', 'LPV', 'ATC', 'Cost/ATC', 'ATC/LPV', 'Checkout (IC)', 'Cost/Checkout', 'Frequency', 'Purchases', 'Purchases Value', 'ROAS', 'AOV', 'Purchase CVR%', 'Reach', 'Profile Visits', 'Follows', 'Impressions (est.)', 'Clicks (est.)', 'Ad Group', 'Creative Key'];
  return pad(toTable(list, cols), 500, cols.length);
}

// ---------- COMBINED ----------
function totals(rows) {
  let spend = 0, purchases = 0, pv = 0;
  for (const r of rows) { spend += num(r.Spend); purchases += num(r.Purchases); pv += num(r.Purchases_Value); }
  return { spend, purchases, pv, cpp: purchases ? spend / purchases : 0, roas: spend ? pv / spend : 0, aov: purchases ? pv / purchases : 0 };
}
const m = totals(sets.meta), t = totals(sets.tt);
const cs = m.spend + t.spend, cp = m.purchases + t.purchases, cv = m.pv + t.pv;
const pct = n => (Number.isFinite(n) ? round(n * 100, 2) + '%' : '');
const combinedRows = [
  { Metric: 'Spend', Meta: round(m.spend, 2), TikTok: round(t.spend, 2), Combined: round(cs, 2) },
  { Metric: 'Purchases', Meta: m.purchases, TikTok: t.purchases, Combined: cp },
  { Metric: 'Cost Per Purchase', Meta: round(m.cpp, 2), TikTok: round(t.cpp, 2), Combined: round(cp ? cs / cp : 0, 2) },
  { Metric: 'Purchases Value', Meta: round(m.pv, 2), TikTok: round(t.pv, 2), Combined: round(cv, 2) },
  { Metric: 'ROAS', Meta: round(m.roas, 4), TikTok: round(t.roas, 4), Combined: round(cs ? cv / cs : 0, 4) },
  { Metric: 'AOV', Meta: round(m.aov, 2), TikTok: round(t.aov, 2), Combined: round(cp ? cv / cp : 0, 2) },
  { Metric: '', Meta: '', TikTok: '', Combined: '' },
  { Metric: 'Spend Mix', Meta: '', TikTok: '', Combined: '' },
  { Metric: 'Meta Share of Combined Spend', Meta: pct(cs ? m.spend / cs : NaN), TikTok: '', Combined: '' },
  { Metric: 'TikTok Share of Combined Spend', Meta: '', TikTok: pct(cs ? t.spend / cs : NaN), Combined: '' },
];
function fmtCombined(metric, value) {
  if (value === '' || value == null) return '';
  if (metric === 'Purchases') return fmtInt(value);
  if (metric.includes('Share')) return String(value);
  if (['ROAS', 'AOV', 'Spend', 'Cost Per Purchase', 'Purchases Value'].includes(metric)) return fmtNum(value, 2);
  return String(value);
}
const combinedValues = pad(combinedRows.map(r => ['Metric', 'Meta', 'TikTok', 'Combined'].map(c => (c === 'Metric' ? r[c] : fmtCombined(r.Metric, r[c])))), 15, 4);

// ---------- sheet payload (ONE batchUpdate per brand; every range is overwritten, so reruns never create duplicates) ----------
const L = period.periodLabel;
const data = [];
const put = (range, values) => data.push({ range, majorDimension: 'ROWS', values });
put("'Meta Overview'!A1:A2", [[brandName + ' - META ADS REPORT'], ['Period: ' + L]]);
put("'Meta Ad Performance'!A1:B2", [[brandName + ' - Meta Ad Performance (Ranked)'], ['Ranked by Spend, highest to lowest', L]]);
put("'Meta Creatives Performance'!A1:D2", [[brandName + ' - Meta Creatives Performance'], ['Same creative combined across all ad sets/campaigns', 'Ranked by total Spend', L, 'live formulas off Meta Ad Performance']]);
put("'Meta Weekly'!A1:B2", [[brandName + ' - Meta Weekly Performance'], ['Ranked best to worst by ROAS', L]]);
put("'TikTok Overview'!A1:A2", [[brandName + ' - TikTok Ads Overview'], ['Period: ' + L]]);
put("'TikTok Ad Performance'!A1:C2", [[brandName + ' - TikTok Ad Performance (Ranked)'], ['Ranked by Spend, highest to lowest', L, 'All ads with spend > 0']]);
put("'TikTok Creatives Performance'!A1:D2", [[brandName + ' - TikTok Creatives Performance'], ['Same creative combined across all ad groups/campaigns', 'Ranked by total Spend', L, 'live formulas off TikTok Ad Performance']]);
put("'TikTok Weekly'!A1:B2", [[brandName + ' - TikTok Weekly Performance'], ['Ranked best to worst by ROAS', L]]);
put("'Combined'!A1:C2", [[brandName + ' - Combined Meta + TikTok Performance'], ['Meta: ' + L, 'TikTok: ' + L, 'EGP']]);
put("'Meta Overview'!A5", metaOverview(sets.meta));
put("'Meta Ad Performance'!A5", metaAdPerformance(sets.metaAds));
put("'Meta Creatives Performance'!A5", creatives(sets.metaAds, false));
